  ('a85da4df-7c76-541d-af49-bee634e775f9', null, (select id from public.skills where slug = 'write-g11-narrative-writing'), null, 'medium',
   $q$Which sentence, added after sentence 1, would best establish why the launch matters to the narrator?$q$, $q$[{"text":"Weather balloons are filled with helium and can rise more than twenty miles into the sky.","is_correct":false,"misconception_token":"fact-not-significance"},{"text":"It was the first experiment we had designed entirely ourselves, and none of us knew whether it would work.","is_correct":true},{"text":"Our teacher had done this project with other classes, and it had always gone smoothly.","is_correct":false,"misconception_token":"undercuts-stakes"},{"text":"The soccer field was muddy that morning, and several people had forgotten their gloves.","is_correct":false,"misconception_token":"detail-not-significance"}]$q$::jsonb, $q$It was the first experiment we had designed entirely ourselves, and none of us knew whether it would work.$q$, $q$The correct choice gives the stakes: the students own this experiment and its success is uncertain. The note that it always went smoothly removes the doubt that makes the lost signal tense.$q$, 'draft', '323f5b14-65ea-5553-9c2c-4a53693e5ffc')
