  ('0ac6b780-e13e-5311-bbae-82b5111588e8', null, (select id from public.skills where slug = 'write-g11-narrative-writing'), null, 'easy',
   $q$Which sentence would best replace sentence 16 as a conclusion that reflects on the experience?$q$, $q$[{"text":"The bus was crowded, so I had to stand for the whole ride back to my side of town.","is_correct":false,"misconception_token":"flat-ending-no-reflection"},{"text":"Oral history projects are a good way for students to learn about the past in their communities.","is_correct":false,"misconception_token":"generic-fact-ending"},{"text":"On the bus, I replayed his voice and realized the project had stopped being homework somewhere around the second glass of lemonade.","is_correct":true},{"text":"Mr. Asante worked as a conductor until the line closed, and he owns a brass pocket watch.","is_correct":false,"misconception_token":"restates-situation"}]$q$::jsonb, $q$On the bus, I replayed his voice and realized the project had stopped being homework somewhere around the second glass of lemonade.$q$, $q$The correct choice reflects on how the narrator's view of the assignment changed, echoing the lemonade from sentence 4. The crowded bus choice adds an event but no reflection.$q$, 'draft', 'd008e018-c6f1-5280-96c4-51d8ae68e90a')
