  ('54144fa8-2ced-5735-a0ac-cbba2e0f71e0', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Read the sentences: "Having spent the summer mapping the cave system. The geology students presented their findings to the park staff." Which revision fixes the fragment?$q$, $q$[{"text":"Having spent the summer mapping the cave system, their findings were presented to the park staff by the students.","is_correct":false,"misconception_token":"dangling-modifier-created"},{"text":"Having spent the summer mapping the cave system, the geology students presented their findings to the park staff.","is_correct":true},{"text":"Having spent the summer mapping the cave system; the geology students presented their findings to the park staff.","is_correct":false,"misconception_token":"semicolon-after-phrase"},{"text":"Having spent the summer mapping the cave system, and the geology students presented their findings to the park staff.","is_correct":false,"misconception_token":"conjunction-creates-fragment"}]$q$::jsonb, $q$Having spent the summer mapping the cave system, the geology students presented their findings to the park staff.$q$, $q$The participial phrase attaches with a comma to the main clause, and its subject, "the geology students," is the group that did the mapping. The passive version fixes the fragment but makes "their findings" seem to have spent the summer mapping.$q$, 'draft', null)
