  ('e9a092df-9060-5b5f-bd51-c6f0cf90cbb8', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'medium',
   $q$Read the sentence: "The solar panels on the gym roof produce more power than the building uses, the extra electricity is sold back to the grid." Which revision fixes the comma splice and shows the logical relationship?$q$, $q$[{"text":"Because the solar panels on the gym roof produce more power than the building uses, the extra electricity is sold back to the grid.","is_correct":true},{"text":"The solar panels on the gym roof produce more power than the building uses, therefore the extra electricity is sold back to the grid.","is_correct":false,"misconception_token":"comma-splice-with-conjunctive-adverb"},{"text":"The solar panels on the gym roof produce more power than the building uses the extra electricity is sold back to the grid.","is_correct":false,"misconception_token":"fused-sentence"},{"text":"Although the solar panels on the gym roof produce more power than the building uses, the extra electricity is sold back to the grid.","is_correct":false,"misconception_token":"illogical-subordinator"}]$q$::jsonb, $q$Because the solar panels on the gym roof produce more power than the building uses, the extra electricity is sold back to the grid.$q$, $q$Producing more power than needed is the reason electricity is sold back, so "Because" shows the cause and makes the first clause dependent. "Therefore" shows the right logic, but with only a comma before it the sentence is still a comma splice.$q$, 'draft', null)
