  ('43f80596-137e-59d2-8334-f1e73acc82d7', null, (select id from public.skills where slug = 'write-g11-sentence-structure'), null, 'hard',
   $q$Read the sentence: "Because the river delta, which had been growing steadily for centuries as sediment washed down from the mountains, began to shrink after the dam was built upstream." Which revision makes it a complete sentence?$q$, $q$[{"text":"The river delta, which had been growing steadily for centuries as sediment washed down from the mountains, began to shrink after the dam was built upstream.","is_correct":true},{"text":"Because the river delta, which had been growing steadily for centuries as sediment washed down from the mountains; began to shrink after the dam was built upstream.","is_correct":false,"misconception_token":"semicolon-misused"},{"text":"The river delta, which had been growing steadily for centuries as sediment washed down from the mountains, because it began to shrink after the dam was built upstream.","is_correct":false,"misconception_token":"subordinator-moved-fragment"},{"text":"Because the river delta had been growing steadily for centuries as sediment washed down from the mountains, which began to shrink after the dam was built upstream.","is_correct":false,"misconception_token":"fragment-reworded"}]$q$::jsonb, $q$The river delta, which had been growing steadily for centuries as sediment washed down from the mountains, began to shrink after the dam was built upstream.$q$, $q$Removing "Because" lets "delta" take "began" as its main verb, so the sentence is independent. Moving "because" to the middle still leaves "delta" without a main verb, since "began" is now inside a dependent clause.$q$, 'draft', null)
