values
  ('c57b28f7-d622-57cb-a621-7bbf9b4a34f8', null, (select id from public.skills where slug = 'write-g11-writing-with-evidence'), null, 'hard',
   $q$Why is it more effective for the writer to quote sentence 3 directly than to paraphrase it?$q$, $q$[{"text":"Direct quotations always count as stronger evidence than paraphrases in any kind of writing.","is_correct":false,"misconception_token":"overgeneralization"},{"text":"Sentence 4 analyzes the exact comparison \"the way someone slams a door,\" so a paraphrase would lose the wording being interpreted.","is_correct":true},{"text":"A paraphrase would make the first paragraph too short to count as a full paragraph.","is_correct":false,"misconception_token":"irrelevant-reason"},{"text":"Quoting the line proves that Marisol's friends were waiting for her on the beach.","is_correct":false,"misconception_token":"misreads-text"}]$q$::jsonb, $q$Sentence 4 analyzes the exact comparison "the way someone slams a door," so a paraphrase would lose the wording being interpreted.$q$, $q$The writer's analysis depends on Osei's specific simile, so the precise words must appear for sentence 4 to make sense. Quotations are not always stronger; they are best when the exact language is what the writer analyzes.$q$, 'draft', '57329ddd-a95d-5346-b2ef-98b651da1a8b')
