  ('1e946823-91e7-5a88-9692-fec114931b1c', null, (select id from public.skills where slug = 'write-g11-writing-with-evidence'), null, 'easy',
   $q$What is the main weakness of the first paragraph (sentences 3 to 6)?$q$, $q$[{"text":"Every point comes from the club's own report, which may present the club in a favorable light.","is_correct":true},{"text":"It quotes the coach directly, and quotations from coaches are not allowed.","is_correct":false,"misconception_token":"invented-rule"},{"text":"It never states a percentage, so the reader cannot judge how many rowers return.","is_correct":false,"misconception_token":"misreads-text"},{"text":"It uses too many sources, which makes the paragraph confusing and hard to follow.","is_correct":false,"misconception_token":"misidentifies-problem"}]$q$::jsonb, $q$Every point comes from the club's own report, which may present the club in a favorable light.$q$, $q$Sentences 3 through 6 all rely on Leaupepe's report, a single source written by the club itself. The paragraph does give a percentage (81 percent in sentence 6), so that choice misreads the draft.$q$, 'draft', 'fcd2195f-c892-56b6-86ef-ca3a8f145083')
