  ('38522204-786c-5ff2-bdc2-d97f67fd00d7', null, (select id from public.skills where slug = 'write-g12-argument-writing'), null, 'easy',
   $q$Which revision of sentence (8) best keeps a formal style and an objective tone?$q$, $q$[{"text":"Archivists have many opinions, and all of them are worth hearing.","is_correct":false,"misconception_token":"vague-wording"},{"text":"Those archivists clearly just want to keep history locked away for themselves.","is_correct":false,"misconception_token":"dismissive-tone"},{"text":"Accuracy is a fair concern, but a careful review process can address it.","is_correct":true},{"text":"Honestly, worrying about a few typos seems kind of silly to me.","is_correct":false,"misconception_token":"keeps-informal-tone"}]$q$::jsonb, $q$Accuracy is a fair concern, but a careful review process can address it.$q$, $q$The correct revision grants that accuracy matters and leads into the review process in sentences (9) and (10). The choice claiming archivists "want to keep history locked away" is more formal than the original but still attacks the archivists' motives instead of their reasoning.$q$, 'draft', 'ae69533e-3a40-5e0c-9356-b6792fac88eb')
