  ('7ac3d917-49fc-58ad-9065-2172f56a2032', null, (select id from public.skills where slug = 'write-g12-capitalization-punctuation'), null, 'medium',
   $q$Which sentence about the storm hyphenates its compound modifiers correctly?$q$, $q$[{"text":"The fast moving storm brought record-breaking rainfall to the plains.","is_correct":false,"misconception_token":"missing-compound-hyphen"},{"text":"The fast-moving storm brought record-breaking-rainfall to the plains.","is_correct":false,"misconception_token":"hyphen-joins-noun"},{"text":"The fast-moving storm brought record-breaking rainfall to the plains.","is_correct":true},{"text":"The fast-moving storm brought record breaking rainfall to the plains.","is_correct":false,"misconception_token":"missing-compound-hyphen"}]$q$::jsonb, $q$The fast-moving storm brought record-breaking rainfall to the plains.$q$, $q$"Fast-moving" and "record-breaking" are each compound adjectives placed before a noun, so both take hyphens, while the nouns "storm" and "rainfall" stay separate. Dropping either hyphen or attaching the noun breaks the convention.$q$, 'draft', null)
