  ('52f13708-07d1-52f5-87d6-0c1e30075890', null, (select id from public.skills where slug = 'write-g12-capitalization-punctuation'), null, 'hard',
   $q$Read the sentence: "The planning committee included Rana Haddad, the treasurer, Tomas Lindqvist, the secretary, and Mei Chen, the coordinator." Which revision makes clear that the committee has exactly three members?$q$, $q$[{"text":"The planning committee included Rana Haddad; the treasurer, Tomas Lindqvist; the secretary, and Mei Chen; the coordinator.","is_correct":false,"misconception_token":"semicolon-wrong-place"},{"text":"The planning committee included: Rana Haddad, the treasurer: Tomas Lindqvist, the secretary: and Mei Chen, the coordinator.","is_correct":false,"misconception_token":"colon-for-semicolon"},{"text":"The planning committee included Rana Haddad, the treasurer; Tomas Lindqvist, the secretary, and Mei Chen, the coordinator.","is_correct":false,"misconception_token":"inconsistent-series-punctuation"},{"text":"The planning committee included Rana Haddad, the treasurer; Tomas Lindqvist, the secretary; and Mei Chen, the coordinator.","is_correct":true}]$q$::jsonb, $q$The planning committee included Rana Haddad, the treasurer; Tomas Lindqvist, the secretary; and Mei Chen, the coordinator.$q$, $q$Each item pairs a name with a title that already uses a comma, so semicolons must separate all three items to show there are three people, not six. Using a semicolon after only the first item leaves the second and third items blurred together.$q$, 'draft', null)
