  ('d6c9e0e1-0551-5b43-b4a8-29c022c8356c', null, (select id from public.skills where slug = 'write-g12-capitalization-punctuation'), null, 'hard',
   $q$Read the sentence: "When the orchestra performed the symphony that Amara Bello composed last spring the audience stood for several minutes." Which revision is punctuated correctly?$q$, $q$[{"text":"When the orchestra performed the symphony that Amara Bello composed, last spring the audience stood for several minutes.","is_correct":false,"misconception_token":"comma-misplaced-in-clause"},{"text":"When the orchestra performed the symphony, that Amara Bello composed last spring, the audience stood for several minutes.","is_correct":false,"misconception_token":"commas-around-restrictive-clause"},{"text":"When the orchestra performed the symphony that Amara Bello composed last spring, the audience stood for several minutes.","is_correct":true},{"text":"When the orchestra performed the symphony that Amara Bello composed last spring; the audience stood for several minutes.","is_correct":false,"misconception_token":"semicolon-after-dependent-clause"}]$q$::jsonb, $q$When the orchestra performed the symphony that Amara Bello composed last spring, the audience stood for several minutes.$q$, $q$The whole introductory clause, including the restrictive "that Amara Bello composed last spring," ends after "spring," so a single comma belongs there. Clauses beginning with "that" are restrictive and are never set off with commas.$q$, 'draft', null)
