  ('82df68dd-f2f5-50bb-aea0-ef47c334d73a', null, (select id from public.skills where slug = 'write-g12-capitalization-punctuation'), null, 'hard',
   $q$Which sentence about the pottery workshop is punctuated correctly throughout?$q$, $q$[{"text":"The two-day workshop covered kiln safety; however, most students wanted more time at the wheel.","is_correct":true},{"text":"The two-day workshop covered kiln safety; however most students wanted more time at the wheel.","is_correct":false,"misconception_token":"missing-comma-after-transition"},{"text":"The two-day workshop covered kiln safety, however, most students wanted more time at the wheel.","is_correct":false,"misconception_token":"comma-splice"},{"text":"The two day workshop covered kiln safety; however, most students wanted more time at the wheel.","is_correct":false,"misconception_token":"missing-compound-hyphen"}]$q$::jsonb, $q$The two-day workshop covered kiln safety; however, most students wanted more time at the wheel.$q$, $q$"Two-day" is a hyphenated compound adjective, and "however" joining two independent clauses needs a semicolon before it and a comma after it. The version with commas around "however" is a comma splice even though the hyphen is right.$q$, 'draft', null)
