  ('5a841f88-a60f-5f01-9bba-93cb35153fb5', null, (select id from public.skills where slug = 'write-g12-capitalization-punctuation'), null, 'hard',
   $q$Read the sentence: "The judges not the coaches selected the final lineup for the gymnastics invitational." Which revision correctly sets off the contrasting element?$q$, $q$[{"text":"The judges not the coaches, selected the final lineup for the gymnastics invitational.","is_correct":false,"misconception_token":"missing-opening-comma"},{"text":"The judges; not the coaches, selected the final lineup for the gymnastics invitational.","is_correct":false,"misconception_token":"semicolon-for-comma"},{"text":"The judges, not the coaches selected the final lineup for the gymnastics invitational.","is_correct":false,"misconception_token":"missing-closing-comma"},{"text":"The judges, not the coaches, selected the final lineup for the gymnastics invitational.","is_correct":true}]$q$::jsonb, $q$The judges, not the coaches, selected the final lineup for the gymnastics invitational.$q$, $q$A contrasting element introduced by "not" interrupts the sentence, so it is set off with commas on both sides. With only the first comma, "the coaches" appears to be the subject of "selected."$q$, 'draft', null)
